/// How the server fills a column with the next number.
///
/// The styles are kept apart because each is restated with different
/// DDL, and a redefinition that restates the wrong one either fails or
/// silently stops the numbering.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum IdentityStyle {
    #[default]
    None,
    /// `GENERATED ALWAYS AS IDENTITY`: an explicit value is refused.
    GeneratedAlways,
    /// `GENERATED BY DEFAULT AS IDENTITY`: an explicit value wins.
    GeneratedByDefault,
    /// A default of `nextval(...)` on an owned sequence, which is what
    /// PostgreSQL's `serial` types expand to.
    SequenceDefault,
    /// MySQL and MariaDB `AUTO_INCREMENT`.
    AutoIncrementKeyword,
    /// SQLite `INTEGER PRIMARY KEY`, which names the rowid rather than
    /// adding a column.
    SqliteRowidAlias,
    /// SQL Server `IDENTITY(seed, increment)`.
    MssqlIdentity,
}

impl IdentityStyle {
    /// Whether a plain INSERT may give the column a value of its own.
    /// GENERATED ALWAYS needs `OVERRIDING SYSTEM VALUE` and SQL Server
    /// IDENTITY needs `IDENTITY_INSERT`, so both refuse one.
    pub fn accepts_explicit_value(self) -> bool {
        !matches!(self, Self::GeneratedAlways | Self::MssqlIdentity)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_the_identities_that_need_an_override_refuse_a_value() {
        assert!(!IdentityStyle::GeneratedAlways.accepts_explicit_value());
        assert!(!IdentityStyle::MssqlIdentity.accepts_explicit_value());
        for style in [
            IdentityStyle::None,
            IdentityStyle::GeneratedByDefault,
            IdentityStyle::SequenceDefault,
            IdentityStyle::AutoIncrementKeyword,
            IdentityStyle::SqliteRowidAlias,
        ] {
            assert!(style.accepts_explicit_value(), "{style:?}");
        }
    }
}
